// Detectar acciones especiales en la respuesta del AI
const output = $json.output || '';

// Función helper para obtener datos de nodos que pueden no estar ejecutados
function getFromNode(nodeName, field) {
  try {
    const node = $(nodeName);
    if (node && node.first && node.first()) {
      return node.first().json[field];
    }
  } catch (e) {
    // Nodo no ejecutado
  }
  return null;
}

// Función para verificar si un nodo fue ejecutado
function wasNodeExecuted(nodeName) {
  try {
    const node = $(nodeName);
    return node && node.isExecuted;
  } catch (e) {
    return false;
  }
}

// Detectar si el mensaje original vino de audio
const isFromAudio = wasNodeExecuted('Merge Audio Data');

// Obtener phoneNumber y phoneNumberId de cualquier fuente disponible
const phoneNumber = $json.phoneNumber || 
  getFromNode('Merge Data', 'phoneNumber') || 
  getFromNode('Merge Audio Data', 'phoneNumber') || 
  getFromNode('Merge Image Data', 'phoneNumber') || 
  getFromNode('Button to Text', 'phoneNumber');

const phoneNumberId = $json.phoneNumberId || 
  getFromNode('Merge Data', 'phoneNumberId') || 
  getFromNode('Merge Audio Data', 'phoneNumberId') || 
  getFromNode('Merge Image Data', 'phoneNumberId') || 
  getFromNode('Button to Text', 'phoneNumberId');

// Obtener nombre del contacto
const contactName = $json.contactName || 
  getFromNode('Merge Data', 'contactName') || 
  getFromNode('Merge Audio Data', 'contactName') || 
  getFromNode('Merge Image Data', 'contactName') || 
  getFromNode('Button to Text', 'contactName');

// Obtener el mensaje original del usuario para detectar tipo de agendamiento
const userMessage = (getFromNode('Merge Data', 'chatInput') || 
  getFromNode('Merge Audio Data', 'chatInput') || 
  getFromNode('Merge Image Data', 'chatInput') || 
  getFromNode('Button to Text', 'chatInput') || '').toLowerCase();

let action = 'send_text';
let cleanMessage = output;
let appointmentType = 'Demo'; // Por defecto

// Detectar tipo de agendamiento basado en lo que pidió el usuario
if (userMessage.includes('seguimiento') || userMessage.includes('cliente') || userMessage.includes('mi proyecto')) {
  appointmentType = 'Seguimiento';
} else if (userMessage.includes('reunion') || userMessage.includes('reunión')) {
  appointmentType = 'Reunion';
} else if (userMessage.includes('cita')) {
  appointmentType = 'Cita';
} else if (userMessage.includes('videollamada')) {
  appointmentType = 'Videollamada';
} else if (userMessage.includes('llamada')) {
  appointmentType = 'Llamada';
} else {
  appointmentType = 'Demo';
}

// Detectar acciones especiales
if (output.includes('<<ACTION:SHOW_CALENDAR>>')) {
  action = 'show_calendar';
  cleanMessage = output.replace('<<ACTION:SHOW_CALENDAR>>', '').trim();
} else if (output.includes('<<ACTION:FOLLOWUP_MEETING>>')) {
  action = 'followup_meeting';
  cleanMessage = output.replace('<<ACTION:FOLLOWUP_MEETING>>', '').trim();
  appointmentType = 'Seguimiento';
} else if (output.includes('<<ACTION:CANCEL_APPOINTMENT>>')) {
  action = 'cancel_appointment';
  cleanMessage = output.replace('<<ACTION:CANCEL_APPOINTMENT>>', '').trim();
} else if (output.includes('<<ACTION:RESCHEDULE_APPOINTMENT>>')) {
  action = 'reschedule_appointment';
  cleanMessage = output.replace('<<ACTION:RESCHEDULE_APPOINTMENT>>', '').trim();
} else if (output.includes('<<ACTION:RESCHEDULE_FOLLOWUP>>')) {
  action = 'reschedule_followup';
  cleanMessage = output.replace('<<ACTION:RESCHEDULE_FOLLOWUP>>', '').trim();
  appointmentType = 'Seguimiento';
} else if (output.includes('<<ACTION:ESCALATE_SUPPORT>>')) {
  action = 'escalate_support';
  cleanMessage = output.replace('<<ACTION:ESCALATE_SUPPORT>>', '').trim();
} else if (output.includes('<<ACTION:SHOW_PLANS>>')) {
  action = 'show_plans';
  cleanMessage = output.replace('<<ACTION:SHOW_PLANS>>', '').trim();
} else if (isFromAudio) {
  // Si es respuesta de texto normal y el usuario envió audio, responder con audio
  action = 'send_audio';
}

return {
  json: {
    action: action,
    output: cleanMessage,
    phoneNumber: phoneNumber,
    phoneNumberId: phoneNumberId,
    contactName: contactName,
    isFromAudio: isFromAudio,
    appointmentType: appointmentType
  }
};

// Generar días disponibles validando horarios, feriados Y disponibilidad real de slots
const config = $('Get Appointments Config').first().json;

// Obtener phoneNumber/phoneNumberId del input (puede venir de diferentes flujos)
let phoneNumber, phoneNumberId, contactName, appointmentType, output, companyName;

// Intentar obtener de Prepare Followup Reschedule Data (flujo de reagendamiento de seguimiento)
try {
  const followupRescheduleData = $('Prepare Followup Reschedule Data').first().json;
  if (followupRescheduleData && followupRescheduleData.phoneNumber) {
    phoneNumber = followupRescheduleData.phoneNumber;
    phoneNumberId = followupRescheduleData.phoneNumberId;
    contactName = followupRescheduleData.contactName;
    appointmentType = 'Seguimiento';
    output = '';
    companyName = '';
  }
} catch (e) {}

// Intentar obtener de Prepare Followup Data (flujo de seguimiento con validación de cliente)
if (!phoneNumber) {
  try {
    const followupData = $('Prepare Followup Data').first().json;
    if (followupData && followupData.phoneNumber) {
      phoneNumber = followupData.phoneNumber;
      phoneNumberId = followupData.phoneNumberId;
      contactName = followupData.contactName;
      appointmentType = followupData.appointmentType || 'Seguimiento';
      output = followupData.output || '';
      companyName = followupData.companyName || '';
    }
  } catch (e) {}
}

// Si no se obtuvo, intentar de Route Action (flujo normal de booking)
if (!phoneNumber) {
  try {
    const routeData = $('Route Action').first().json;
    phoneNumber = routeData.phoneNumber;
    phoneNumberId = routeData.phoneNumberId;
    contactName = routeData.contactName;
    appointmentType = routeData.appointmentType || 'Demo';
    output = routeData.output || '';
  } catch (e) {}
}

// Si no se obtuvo, intentar de Parse Reschedule Event (flujo de reprogramación simplificado)
if (!phoneNumber) {
  try {
    const parseData = $('Parse Reschedule Event').first().json;
    phoneNumber = parseData.phoneNumber;
    phoneNumberId = parseData.phoneNumberId;
    contactName = parseData.clientName;
    appointmentType = 'Demo';
  } catch (e) {}
}

// Si no se obtuvo, intentar de Parse Event To Delete (flujo antiguo)
if (!phoneNumber) {
  try {
    const parseData = $('Parse Event To Delete').first().json;
    phoneNumber = parseData.phoneNumber;
    phoneNumberId = parseData.phoneNumberId;
    contactName = parseData.clientName;
    appointmentType = 'Demo';
  } catch (e) {}
}

// Si no se obtuvo, intentar de Prepare Reschedule Data (flujo desde recordatorio)
if (!phoneNumber) {
  try {
    const inputData = $('Prepare Reschedule Data').first().json;
    phoneNumber = inputData.phoneNumber;
    phoneNumberId = inputData.phoneNumberId;
    contactName = inputData.contactName;
    appointmentType = 'Demo';
  } catch (e) {}
}

// Si todavía no hay, usar el input directo
if (!phoneNumber) {
  const inputData = $input.first().json;
  phoneNumber = inputData.phoneNumber;
  phoneNumberId = inputData.phoneNumberId;
  contactName = inputData.contactName || inputData.clientName;
  appointmentType = inputData.appointmentType || 'Demo';
  output = inputData.output || '';
}

// Normalizar tipo para usar en btnId (sin espacios ni caracteres especiales)
const typeCode = appointmentType === 'Seguimiento' ? 'seg' : 'demo';

const weekSchedule = config.data?.weekSchedule || {};
const holidays = config.data?.holidays || [];
const busyDates = config.data?.busyDates || {};

const dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const dayNamesES = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const monthsES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];

const now = DateTime.now().setZone('America/Santiago');
const days = [];
let checkDate = now;
let attempts = 0;

while (days.length < 3 && attempts < 30) {
  checkDate = checkDate.plus({ days: 1 });
  attempts++;

  const dayOfWeek = checkDate.weekday % 7;
  const dayName = dayNames[dayOfWeek];
  const dateKey = checkDate.toFormat('yyyy-MM-dd');

  const dayConfig = weekSchedule[dayName] || { enabled: false };
  if (!dayConfig.enabled) continue;

  if (holidays.includes(dateKey)) continue;

  if (busyDates[dateKey] && busyDates[dateKey].isFull === true) {
    continue;
  }

  const startHour = parseInt((dayConfig.start || '09:00').split(':')[0]);
  const endHour = parseInt((dayConfig.end || '18:00').split(':')[0]);

  if (busyDates[dateKey]) {
    const availableCount = busyDates[dateKey].availableSlots || 0;
    if (availableCount <= 0) continue;
  }

  days.push({
    date: dateKey,
    display: `${dayNamesES[dayOfWeek]} ${checkDate.day} ${monthsES[checkDate.month - 1]}`,
    btnId: `day_${typeCode}_${dateKey}`
  });
}

return {
  json: {
    phoneNumber: phoneNumber,
    phoneNumberId: phoneNumberId,
    contactName: contactName,
    availableDays: days,
    appointmentType: appointmentType || 'Demo',
    output: output || '',
    companyName: companyName || ''
  }
};

