// Parsear fecha en texto natural español
const inputData = $('Check Email Booking').first().json;
const config = $input.first().json;
const dateText = (inputData.messageText || '').toLowerCase().trim();

const weekSchedule = config.data?.weekSchedule || {};
const holidays = config.data?.holidays || [];

// Meses en español
const meses = {
  'enero': 0, 'ene': 0,
  'febrero': 1, 'feb': 1,
  'marzo': 2, 'mar': 2,
  'abril': 3, 'abr': 3,
  'mayo': 4, 'may': 4,
  'junio': 5, 'jun': 5,
  'julio': 6, 'jul': 6,
  'agosto': 7, 'ago': 7,
  'septiembre': 8, 'sep': 8, 'sept': 8,
  'octubre': 9, 'oct': 9,
  'noviembre': 10, 'nov': 10,
  'diciembre': 11, 'dic': 11
};

const dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];

let parsedDate = null;
let parsedTime = null;

// Patrones de fecha: "15 de enero", "15 enero", "enero 15"
const datePatterns = [
  /(\d{1,2})\s*(?:de)?\s*(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre|ene|feb|mar|abr|may|jun|jul|ago|sep|sept|oct|nov|dic)/i,
  /(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre|ene|feb|mar|abr|may|jun|jul|ago|sep|sept|oct|nov|dic)\s*(\d{1,2})/i
];

for (const pattern of datePatterns) {
  const match = dateText.match(pattern);
  if (match) {
    const day = parseInt(match[1]) || parseInt(match[2]);
    const monthName = (match[2] || match[1]).toLowerCase();
    const month = meses[monthName];

    if (month !== undefined && day >= 1 && day <= 31) {
      const now = new Date();
      let year = now.getFullYear();

      // Si el mes ya pasó este año, usar el año siguiente
      if (month < now.getMonth() || (month === now.getMonth() && day < now.getDate())) {
        year++;
      }

      parsedDate = new Date(year, month, day);
      break;
    }
  }
}

// Patrones de hora: "14:00", "2 pm", "14 horas", "a las 14"
const timePatterns = [
  /(\d{1,2}):(\d{2})/,
  /(?:a las|las)?\s*(\d{1,2})\s*(?:hrs?|horas?)?/i,
  /(\d{1,2})\s*(?:am|pm)/i
];

for (const pattern of timePatterns) {
  const match = dateText.match(pattern);
  if (match) {
    let hour = parseInt(match[1]);
    const minute = match[2] ? parseInt(match[2]) : 0;

    // Manejar AM/PM
    if (dateText.includes('pm') && hour < 12) {
      hour += 12;
    } else if (dateText.includes('am') && hour === 12) {
      hour = 0;
    }

    if (hour >= 0 && hour <= 23 && minute >= 0 && minute <= 59) {
      parsedTime = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
      break;
    }
  }
}

// Validar que se pudo parsear
if (!parsedDate || !parsedTime) {
  return {
    json: {
      ...inputData,
      isValid: false,
      error: 'No pude entender la fecha. Por favor usa el formato: "15 de enero a las 14:00" o agenda desde la web.'
    }
  };
}

const dateKey = parsedDate.toISOString().split('T')[0];
const dayOfWeek = parsedDate.getDay();
const dayName = dayNames[dayOfWeek];

// Validar que no sea pasado
const now = new Date();
if (parsedDate < now) {
  return {
    json: {
      ...inputData,
      isValid: false,
      error: 'Esa fecha ya pasó. Por favor elige una fecha futura.'
    }
  };
}

// Validar que el día esté habilitado
const dayConfig = weekSchedule[dayName] || { enabled: false };
if (!dayConfig.enabled) {
  const dias = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
  return {
    json: {
      ...inputData,
      isValid: false,
      error: `Lo siento, los ${dias[dayOfWeek]}s no hay atención disponible. Por favor elige otro día.`
    }
  };
}

// Validar que no sea feriado
if (holidays.includes(dateKey)) {
  return {
    json: {
      ...inputData,
      isValid: false,
      error: 'Ese día es feriado o está bloqueado. Por favor elige otra fecha.'
    }
  };
}

// Validar horario dentro del rango configurado
const [startHour] = dayConfig.start.split(':').map(Number);
const [endHour] = dayConfig.end.split(':').map(Number);
const [requestHour] = parsedTime.split(':').map(Number);

if (requestHour < startHour || requestHour >= endHour) {
  return {
    json: {
      ...inputData,
      isValid: false,
      error: `El horario de atención ese día es de ${dayConfig.start} a ${dayConfig.end} hrs. Por favor elige un horario dentro de ese rango.`
    }
  };
}

// Todo válido
return {
  json: {
    ...inputData,
    isValid: true,
    selectedDay: dateKey,
    selectedTime: parsedTime,
    parsedDateDisplay: parsedDate.toLocaleDateString('es-CL', { day: '2-digit', month: 'long', year: 'numeric' })
  }
};

